===WORLD===
const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // Restore persisted state for a simulated reload or a seeded scenario. A browser keeps
    // localStorage and the URL hash across a reload; the harness reproduces exactly that so the
    // persistence and routing-reload scenarios exercise real behaviour rather than a fresh page.
    if (this._restore) {
      if (this._restore.todos != null)
        this.window.localStorage.setItem('todos-vanillajs', this._restore.todos);
      if (this._restore.hash) this.window.location.hash = this._restore.hash;
      this._restore = null;
    }

    // The app must EXECUTE, not merely be present. happy-dom does NOT run scripts the parser
    // sees, so the harness runs app.js itself via window.eval. DOMContentLoaded never fires from
    // write()/close(), so the harness dispatches it (and load) so a DOMContentLoaded-bound app
    // initialises correctly.
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange, so a TodoMVC router
    // listening for hashchange is unreachable without this. Route the two ways a real browser
    // changes the hash so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target?.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Seed the app with a known todo set, then (re)load so the app renders it. Used by the
  // "the app has the following todos" step.
  async seedTodos(todos) {
    this._restore = { todos: JSON.stringify(todos), hash: '' };
    await this._reload();
  }

  // Simulate a browser reload: the URL hash and localStorage survive, everything else is fresh.
  async reloadApp() {
    this._restore = {
      todos: this.window.localStorage.getItem('todos-vanillajs'),
      hash: this.window.location.hash,
    };
    await this._reload();
  }

  async _reload() {
    await this.disposeApp();
    this.loadApp();
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

const assert = require('node:assert');
const { Given, When, Then } = require('@cucumber/cucumber');

// ---- helpers ---------------------------------------------------------------

function liItems() {
  return Array.from(this.document.querySelectorAll('.todo-list li'));
}
function firstLi() {
  const items = liItems.call(this);
  assert(items.length >= 1, 'expected at least one todo item in .todo-list');
  return items[0];
}
function findLiByLabel(label) {
  const li = liItems.call(this).find((el) => el.querySelector('label').textContent === label);
  assert(li, `expected a todo item with label "${label}"`);
  return li;
}
function editInputOf(li) {
  const el = li.querySelector('.edit');
  assert(el, 'expected an .edit input on the todo item');
  return el;
}
function dispatchKey(win, el, key) {
  el.dispatchEvent(new win.KeyboardEvent('keydown', { bubbles: true, cancelable: true, key }));
}
function clickToggle(win, li) {
  const t = li.querySelector('.toggle');
  assert(t, 'expected a .toggle input on the todo item');
  t.checked = !t.checked;
  t.dispatchEvent(new win.Event('change', { bubbles: true }));
}
function persisted(key) {
  const raw = this.window.localStorage.getItem(key);
  assert(raw !== null, `expected localStorage key "${key}" to exist`);
  return JSON.parse(raw);
}
function parseValue(raw) {
  if (raw === 'true') return true;
  if (raw === 'false') return false;
  const m = /^"([\s\S]*)"$/.exec(raw);
  return m ? m[1] : raw;
}

// ---- given -----------------------------------------------------------------

Given('the app is loaded', function () {
  assert(this.document, 'verification support: app was not loaded');
});

Given('the app has the following todos:', async function (dataTable) {
  const todos = dataTable.hashes().map((row, i) => ({
    id: i + 1,
    title: row.title,
    completed: row.completed === 'true',
  }));
  await this.seedTodos(todos);
});

Given('the app is reloaded', async function () {
  await this.reloadApp();
});

// ---- when ------------------------------------------------------------------

When('the user types {string} into {string}', function (text, selector) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  el.value = text;
  el.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('the user presses Enter in {string}', function (selector) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  dispatchKey(this.window, el, 'Enter');
});

When('the user presses Enter in the edit input of the first todo item', function () {
  dispatchKey(this.window, editInputOf(firstLi.call(this)), 'Enter');
});

When('the user presses Enter in the edit input of the todo item with label {string}', function (label) {
  dispatchKey(this.window, editInputOf(findLiByLabel.call(this, label)), 'Enter');
});

When('the user presses Escape in {string}', function (selector) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  dispatchKey(this.window, el, 'Escape');
});

When('the user presses Escape in the edit input of the first todo item', function () {
  dispatchKey(this.window, editInputOf(firstLi.call(this)), 'Escape');
});

When('the user clicks {string}', function (selector) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  if (selector === '#toggle-all') {
    el.checked = !el.checked;
    el.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  } else {
    el.dispatchEvent(new this.window.Event('click', { bubbles: true }));
  }
});

When('the user clicks the toggle of the first todo item', function () {
  clickToggle(this.window, firstLi.call(this));
});

When('the user clicks the toggle of the second todo item', function () {
  const items = liItems.call(this);
  assert(items.length >= 2, 'expected at least two todo items');
  clickToggle(this.window, items[1]);
});

When('the user clicks the toggle of the todo item with label {string}', function (label) {
  clickToggle(this.window, findLiByLabel.call(this, label));
});

When('the user clicks the destroy button of the first todo item', function () {
  const li = firstLi.call(this);
  const btn = li.querySelector('.destroy');
  assert(btn, 'expected a .destroy button on the todo item');
  btn.dispatchEvent(new this.window.Event('click', { bubbles: true }));
});

When('the user double-clicks the label of the first todo item', function () {
  const label = firstLi.call(this).querySelector('label');
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

When('the user double-clicks the label of the todo item with label {string}', function (label) {
  const l = findLiByLabel.call(this, label).querySelector('label');
  l.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

When('the user sets the edit input of the first todo item to {string}', function (text) {
  editInputOf(firstLi.call(this)).value = text;
});

When('the user sets the edit input of the todo item with label {string} to {string}', function (label, text) {
  editInputOf(findLiByLabel.call(this, label)).value = text;
});

When('the edit input of the first todo item loses focus', function () {
  editInputOf(firstLi.call(this)).blur();
});

When('the user navigates to {string}', function (hash) {
  this.navigate(hash);
});

// ---- then ------------------------------------------------------------------

Then('the element with id {string} is hidden', function (id) {
  const el = this.document.getElementById(id);
  assert(el, `expected element with id "${id}"`);
  assert(el.hidden === true, `expected #${id} to be hidden`);
});

Then('{string} is hidden', function (selector) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  assert(el.hidden === true, `expected ${selector} to be hidden`);
});

Then('{string} is focused', function (selector) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  assert(this.document.activeElement === el, `expected ${selector} to be focused`);
});

Then('the {string} input value is empty', function (selector) {
  const el = this.document.querySelector(selector);
  assert(el, `expected element matching ${selector}`);
  assert(el.value === '', `expected ${selector} value to be empty, got "${el.value}"`);
});

Then(/^(.+) contains exactly (\d+) todo items?\.?$/, function (selector, n) {
  const sel = selector.replace(/^"|"$/g, '');
  const count = this.document.querySelectorAll(`${sel} li`).length;
  assert.strictEqual(count, n, `expected ${sel} to contain exactly ${n} todo items, got ${count}`);
});

Then('the first todo item\'s label reads {string}', function (label) {
  const text = firstLi.call(this).querySelector('label').textContent;
  assert.strictEqual(text, label, `expected first todo item label to read "${label}", got "${text}"`);
});

Then('the remaining todo item\'s label reads {string}', function (label) {
  const items = liItems.call(this);
  assert.strictEqual(items.length, 1, `expected exactly one remaining todo item, got ${items.length}`);
  const text = items[0].querySelector('label').textContent;
  assert.strictEqual(text, label, `expected remaining label to read "${label}", got "${text}"`);
});

Then('the first todo item has class {string}', function (cls) {
  assert(firstLi.call(this).classList.contains(cls), `expected first todo item to have class "${cls}"`);
});

Then('the first todo item does not have class {string}', function (cls) {
  assert(!firstLi.call(this).classList.contains(cls), `expected first todo item not to have class "${cls}"`);
});

Then('no todo item has class {string}', function (cls) {
  const withClass = liItems.call(this).filter((li) => li.classList.contains(cls));
  assert.strictEqual(withClass.length, 0, `expected no todo item to have class "${cls}", found ${withClass.length}`);
});

Then('every todo item has class {string}', function (cls) {
  const items = liItems.call(this);
  assert(items.length > 0, 'expected at least one todo item');
  const all = items.every((li) => li.classList.contains(cls));
  assert(all, `expected every todo item to have class "${cls}"`);
});

Then('the first todo item\'s edit input value is {string}', function (value) {
  const v = editInputOf(firstLi.call(this)).value;
  assert.strictEqual(v, value, `expected edit input value "${value}", got "${v}"`);
});

Then('the edit input of the first todo item is focused', function () {
